package com.contextgraph.controller; import com.contextgraph.model.Document; import com.contextgraph.service.DocumentService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*; @RestController @RequestMapping("/api/documents") public class DocumentController{final DocumentService s;public DocumentController(DocumentService s){this.s=s;}@GetMapping public List<Document>list(Authentication a){return s.list(a.getName());}@PostMapping(value="/upload",consumes="multipart/form-data")public Document upload(Authentication a,@RequestParam("file")MultipartFile f)throws Exception{return s.upload(a.getName(),f);}@GetMapping("/{id}")public Document get(Authentication a,@PathVariable Long id){return s.get(a.getName(),id);}@DeleteMapping("/{id}")public Map<String,String>delete(Authentication a,@PathVariable Long id)throws Exception{s.delete(a.getName(),id);return Map.of("message","Document deleted.");}}